UPDATE term_article_sections SET heading='Direction in Antiochus''s sign doctrine',body='Antiochus uses hearing and seeing as directional relations between signs rather than names for an ordinary mutual aspect. His application to travel and danger belongs to the historical doctrine''s particular use, not to a general rule that every configured sign pair hears and sees alike.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='hearing-seeing-relation') AND section_key='direction';
UPDATE term_article_sections SET heading='Natural opposition without the 180° aspect',body='Al-Bīrūnī (§377) reports Abū Maʿshar''s non-aspecting pairs as natural opposites. Examples include Aries with Virgo and Pisces with Libra by correspondence in course, and Gemini with Capricorn and Cancer with Sagittarius by correspondence in power. Their name therefore does not signify geometrical opposition.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='natural-opposition') AND section_key='distinction';
UPDATE term_article_sections SET heading='Why a natural sextile need not be sixty degrees',body='Al-Bīrūnī (§377) describes Abū Maʿshar''s natural sextiles among non-beholding signs: Aries with Pisces and Virgo with Libra by power, and Gemini with Cancer and Sagittarius with Capricorn by course. The relation derives from parallel or complementary celestial behavior, not a 60° aspect. The qualitative judgment in another translated witness is disputed and must remain attributed to that textual stream.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='natural-sextile') AND section_key='distinction';
UPDATE term_article_sections SET heading='Agreement by a shared planetary ruler',body='Al-Bīrūnī (§377) reports that Abū Maʿshar also describes signs ruled by the same planet as agreeing in course or path. He distinguishes that terminology from his own account of paired signs sharing a celestial parallel. Agreement by a common ruler must therefore not be silently equated with agreement by equal daylight or rising times.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='signs-agreeing-in-path') AND section_key='principle';
UPDATE term_article_sections SET heading='Complementary day and night lengths',body='Al-Bīrūnī (§377) describes one relation for signs equidistant from an equinox: their daily and nightly hours correspond inversely, and their ascensions are equal in all places. Aries–Pisces and Taurus–Aquarius are named examples. This is not identical to agreement in course around a solstitial point, nor does it imply an ordinary Ptolemaic aspect.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='signs-agreeing-in-power') AND section_key='principle';
UPDATE term_article_sections SET heading='Ascensional correspondence, with source-dependent naming',body='Al-Bīrūnī (§377) distinguishes signs equidistant from an equinoctial point (equal ascensions) from signs on the same declination parallel equidistant from a solstice (correspondence in course). He notes that different books give these relations different names. The specific term ''agreeing in zone'' must therefore be tied to its source rather than collapsed into all mirrored-sign doctrines.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='signs-agreeing-in-zone') AND section_key='geometry';
UPDATE term_article_sections SET heading='A graded label, not one universal sign list',body='Al-Bīrūnī (§353) includes Aries, Taurus and Leo among half-voiced figures; his adjacent classes assign Capricorn and Aquarius weaker voice and Cancer, Scorpio and Pisces no voice. Abū Maʿshar''s separately recorded half- or moderate-voiced sequence includes Sagittarius as well. The similar English headings do not make these authors'' lists interchangeable.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='half-voiced-sign') AND section_key='scope';
UPDATE term_article_sections SET heading='Human figures and mixed zodiacal images',body='Al-Bīrūnī''s sign-image discussion distinguishes human from four-footed figures and reports a specifically Indian attribution that includes Gemini, Virgo and Libra together with portions of other composite figures. The classification can concern part of a sign''s image, not always its entire thirty-degree span. Report memberships by source rather than forcing a universal human-sign list.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='human-sign') AND section_key='variants';
UPDATE term_article_sections SET heading='Whole and partial four-footed figures',body='In al-Bīrūnī''s sign-image discussion, Aries, Taurus and Leo have four-footed figures; the hind part of Sagittarius and, in some accounts, the front part of Capricorn may also be counted. A mixed image therefore requires attention to which portion the author means. Quadruped is an iconographic class, independent of triplicity or zodiacal aspect.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='quadruped-sign') AND section_key='distinction';
UPDATE term_article_sections SET heading='Voice categories differ among authorities',body='Al-Bīrūnī (§353) describes Gemini, Virgo and Libra as loud-voiced, with Gemini particularly capable of speech. This provides a comparison for powerful-voiced sign categories, but does not establish that Abū Maʿshar''s list has identical membership. Each classification requires its author and sign list to be identified.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='powerful-voiced-sign') AND section_key='scope';
UPDATE term_article_sections SET heading='Weak voice in al-Bīrūnī''s account',body='Al-Bīrūnī (§353) names Capricorn and Aquarius as weak-voiced. In the same classification he distinguishes them from half-voiced Aries, Taurus and Leo, and from the voiceless Cancer, Scorpio and Pisces. Weak voice is thus a relative rank inside a source''s sign-image taxonomy, not a measure of any person''s actual speech.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='weak-voiced-sign') AND section_key='scope';
UPDATE term_article_sections SET heading='Voiceless creatures in a specific historical list',body='Al-Bīrūnī (§353) places Cancer, Scorpio and Pisces in the voiceless class. This classification concerns the creatures represented by their sign images; it cannot determine the physical speech capacity of a person. Bonatti''s later iconographic categories should retain their own attributed membership.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='voiceless-sign') AND section_key='scope';
UPDATE term_article_sections SET heading='Source-specific fertility symbolism',body='In al-Bīrūnī''s §354, Aries, Taurus, Libra, Sagittarius and Aquarius are associated with smaller families, while particular portions of Taurus and Capricorn, as well as Leo and Virgo, appear in a stricter sterility class. This historical differentiation means ''small-family'' and ''barren'' cannot be treated as automatic synonyms or as medical predictions.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='barren-sign') AND section_key='scope';
UPDATE term_article_sections SET heading='Source-specific fertile signs and partial signs',body='Al-Bīrūnī (§354) associates Cancer, Scorpio, Pisces and the hind portion of Capricorn with large families. He discusses additional mixed-sign symbolism and multiple births separately. The named relation records a historical classification, not a clinical assessment of fertility or a standalone natal prediction.',editorial_notes='Batch 08: source-scoped technical difference from historical author or direct evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='fecund-sign') AND section_key='scope';
